const D = { energy:.6, scale:1, hue:88, speed:1, density:.5, x:.5, y:.45, chub:.55, limb:.55, sleepy:.6, pose:'hang', style:'felt', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------- helpers ----------
const u = Math.min(width, height);
const sc = (u/600) * P.scale * (1 + A.rms*0.18);
const ax = P.x*width, ay = P.y*height;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const rot2 = (x, y, a) => [x*Math.cos(a) - y*Math.sin(a), x*Math.sin(a) + y*Math.cos(a)];
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat; // tolerate t0 resets
S.lastBeat = K.beat;

// seed-keyed cached structures (rebuilt when seed changes)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.leaves = []; for (let i = 0; i < 14; i++) S.leaves.push({ o: fr(i*3+1)*2-1, s: .7 + fr(i*3+2)*.8, a: (fr(i*3+3)-.5)*1.4, up: fr(i*3+4) > .5 ? 1 : -1 });
  S.tufts  = []; for (let i = 0; i < 44; i++) S.tufts.push({ q: fr(i*7+40)*6.283, l: .6 + fr(i*7+41)*.9, j: fr(i*7+42)*6.283 });
  S.stars  = []; for (let i = 0; i < 9;  i++) S.stars.push({ a: fr(i*5+90)*6.283, r: .55 + fr(i*5+91)*.75, p: fr(i*5+92)*6.283 });
}

// ---------- rhythm: HALF-TEMPO comedy ----------
const e = P.energy;
const bt = K.beat * P.speed * 0.5;                       // the sloth clock
const late = Math.pow(1 - ((K.phase + 0.55) % 1), 3);    // reacts half a beat LATE
const amp = (0.10 + 0.24*e) * (0.55 + 0.75*K.intensity);
const drift = Math.sin(K.t*0.21 + P.seed*0.7);           // slow guaranteed drift
const sway = Math.sin(bt*TAU/4) * amp + drift*0.06;
const partyBob = (K.intensity > 0.75 ? Math.sin(K.beat*P.speed*TAU) * 2.5 * e : 0);

// ---------- style palettes (genuinely different disciplines) ----------
const H = ((P.hue % 360) + 360) % 360;
let fur, fur2, faceC, patchC, lineC, lw, fuzzOn = false, stitchOn = false, hatchOn = false, blushOn = false, glowOn = false;
if (P.style === 'ink')        { fur=[H,10,97]; fur2=[H,16,88]; faceC=[H,5,99];            patchC=[H,32,30]; lineC=[H,42,20];  lw=3;   hatchOn = true; }
else if (P.style === 'neon')  { fur=[H,52,15]; fur2=[H,56,22]; faceC=[H,46,25];           patchC=[H,72,58]; lineC=[H,88,100]; lw=2.4; glowOn = true; }
else if (P.style === 'pastel'){ fur=[H,24,93]; fur2=[H,30,84]; faceC=[(H+28)%360,10,100]; patchC=[H,36,58]; lineC=[H,28,66];  lw=0;   blushOn = true; }
else                          { fur=[H,30,62]; fur2=[H,34,52]; faceC=[(H+22)%360,16,90];  patchC=[H,42,28]; lineC=[H,38,36];  lw=1.6; fuzzOn = true; stitchOn = true; }
const F  = c => fill(c[0], c[1], c[2]);
const SK = (c, w) => { if (w > 0) { stroke(c[0], c[1], c[2]); strokeWeight(w); } else noStroke(); };

// ---------- morphs ----------
const bw = 92 + P.chub*48, bh = 122 + P.chub*20;
const armLen = 95 + P.limb*55;
const hangLen = armLen*0.95;
const armW = 19 + P.chub*7, legW = 15 + P.chub*5;

// ---------- lazy blissful blink ----------
const bcycI = Math.floor(bt/5);
const bph = ((bt/5) % 1 + 1) % 1;
const blinkAt = 0.30 + fr(bcycI + 31)*0.5;
let eyeOpen = constrain(0.85 - P.sleepy*0.6 + (K.intensity - 0.5)*0.4, 0.06, 1);
const bd = Math.abs(bph - blinkAt);
if (bd < 0.08) eyeOpen *= constrain(Math.pow(bd/0.08, 1.4), 0.02, 1);

// ---------- butterfly friend (world space) — sloth's eyes track it ----------
const bfx = width  * (0.5 + 0.34*Math.sin(K.t*0.19 + P.seed*2.1));
const bfy = height * (0.34 + 0.20*Math.sin(K.t*0.31 + 1.7) + 0.05*Math.sin(K.t*1.3));
const lookA = Math.atan2(bfy - (ay - 40*sc), bfx - ax);
const px2 = Math.cos(lookA)*2.6, py2 = Math.sin(lookA)*1.8;

// ---------- reusable pieces ----------
function fuzzRing(x, y, w2, h2, n, i0) {
  if (!fuzzOn) return;
  SK(fur2, 1.4);
  for (let i = 0; i < n; i++) {
    const t = S.tufts[(i + i0) % S.tufts.length];
    const cx2 = x + Math.cos(t.q) * w2 * 0.5, cy2 = y + Math.sin(t.q) * h2 * 0.5;
    const wig = Math.sin(K.t*1.7 + t.j) * 1.5;
    line(cx2, cy2, cx2 + Math.cos(t.q)*(6*t.l) + wig, cy2 + Math.sin(t.q)*(6*t.l));
  }
}

function tube(x1, y1, x2, y2, bow, w) { // outlined felt limb
  noFill();
  const c1x = x1 + bow, c1y = lerp(y1, y2, 0.4);
  const c2x = x2 + bow*0.6, c2y = lerp(y1, y2, 0.75);
  if (lw > 0) { stroke(lineC[0], lineC[1], lineC[2]); strokeWeight(w + lw*1.6); bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2); }
  stroke(fur[0], fur[1], fur[2]); strokeWeight(w);
  bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);
}

function claws(x, y, a, spread) {
  push(); translate(x, y); rotate(a);
  SK(fur2, 3.6); noFill();
  for (let i = -1; i <= 1; i++) {
    const cx3 = i * (5 + spread*2);
    bezier(cx3, 0, cx3 + 2, 7, cx3 + 4, 10, cx3 + 2, 15);
  }
  pop();
}

function head(hx, hy, tilt) {
  push(); translate(hx, hy); rotate(tilt);
  const hr = 47 + P.chub*7;
  // treble sparkle halo (baseline twinkle + audio on top)
  const sn = Math.round(3 + P.density*5);
  push(); blendMode(ADD); noStroke();
  for (let i = 0; i < sn; i++) {
    const st2 = S.stars[i % S.stars.length];
    const tw = 0.25 + 0.75*(0.5 + 0.5*Math.sin(K.t*2.3 + st2.p));
    fill((H + 60) % 360, 30, 100, tw * (5 + K.swell*9 + A.treble*60));
    const rr = hr * st2.r * 1.6;
    circle(Math.cos(st2.a + K.t*0.12)*rr, Math.sin(st2.a + K.t*0.12)*rr*0.8 - 6, 3 + tw*2.5);
  }
  blendMode(BLEND); pop();
  F(fur); SK(lineC, lw); ellipse(0, 0, hr*2, hr*1.84);
  fuzzRing(0, 0, hr*2, hr*1.84, Math.round(8 + P.density*10), 13);
  F(faceC); noStroke(); ellipse(0, 3, hr*1.5, hr*1.34);
  // signature slanted eye patches
  F(patchC);
  push(); translate(-16, -3); rotate(-0.45); ellipse(0, 0, 32, 14); pop();
  push(); translate(16, -3); rotate(0.45); ellipse(0, 0, 32, 14); pop();
  // eyes (track the butterfly) or blissful closed arcs
  if (eyeOpen > 0.18) {
    if (glowOn) fill((H+140)%360, 55, 100); else fill(0, 0, 10);
    noStroke();
    ellipse(-16 + px2, -3 + py2, 7.5, 7.5*eyeOpen);
    ellipse( 16 + px2, -3 + py2, 7.5, 7.5*eyeOpen);
    fill(0, 0, 100, 85);
    circle(-17.5 + px2, -4.5 + py2*0.5, 2.2);
    circle( 14.5 + px2, -4.5 + py2*0.5, 2.2);
  } else {
    SK([0, 0, glowOn ? 90 : 16], 2); noFill();
    arc(-16, -2, 13, 9, 0.15, PI - 0.15);
    arc( 16, -2, 13, 9, 0.15, PI - 0.15);
  }
  // nose + blissful smile (breathes with K.swell)
  noStroke(); F([H, 34, 20]); ellipse(0, 10, 11, 8);
  SK([H, 34, glowOn ? 85 : 24], 2.2); noFill();
  arc(0, 15, 24, 12 + 5*K.swell + 4*late*e, 0.3, PI - 0.3);
  if (blushOn) { noStroke(); fill((H+330)%360, 42, 100, 45); circle(-28, 9, 11); circle(28, 9, 11); }
  // low-intensity sections: floating z's
  if (K.intensity < 0.38) {
    noStroke(); textAlign(CENTER, CENTER);
    for (let i = 0; i < 3; i++) {
      const zp = ((K.t*0.13 + i*0.33) % 1 + 1) % 1;
      fill(H, 20, glowOn ? 100 : 75, (1 - zp)*55);
      textSize(13 + i*5 + zp*9);
      text('z', hr*0.9 + zp*34 + i*9, -hr*0.8 - zp*70 - i*10);
    }
  }
  pop();
}

function bodyBlob(cx4, cy4, rotA, headNod, headTilt) {
  push(); translate(cx4, cy4); rotate(rotA);
  // soft halo (bass glow on top of clk baseline)
  push(); blendMode(ADD); noStroke();
  fill(H, 45, 85, 4 + A.bass*20 + K.pulse*2 + (glowOn ? 5 : 0));
  ellipse(0, 0, bw*1.9, bh*1.7);
  if (glowOn) { fill(H, 70, 100, 7); ellipse(0, 0, bw*1.45, bh*1.3); }
  blendMode(BLEND); pop();
  F(fur); SK(lineC, lw);
  ellipse(0, 4, bw, bh);
  F(fur2); noStroke();
  ellipse(0, 16, bw*0.62, bh*0.55);
  fuzzRing(0, 4, bw, bh, Math.round(10 + P.density*16), 0);
  if (stitchOn) {
    SK([H, 22, 82], 1.5); noFill();
    for (let i = 0; i < 7; i++) { const a0 = -2.6 + i*0.32; arc(0, 16, bw*0.66, bh*0.59, a0, a0 + 0.16); }
  }
  if (hatchOn) {
    SK([H, 36, 34], 1);
    for (let i = 0; i < 7; i++) {
      const yy = -bh*0.30 + i*(bh*0.105);
      const hw = bw*0.42*Math.sqrt(Math.max(0.05, 1 - Math.pow((yy - 4)/(bh*0.5), 2)));
      line(-hw + 6, yy, hw, yy - 8);
    }
  }
  head(0, -bh*0.52 + late*3*e + partyBob, headTilt + headNod);
  pop();
}

// =============== DRAW ===============
push();
translate(ax, ay);
scale(sc);

if (P.pose === 'hang') {
  // --- branch with leaves ---
  const brC = P.style === 'ink' ? faceC : (glowOn ? [H, 50, 12] : [25, 45, 35]);
  F(brC); SK(lineC, Math.max(lw, glowOn ? 2 : 0));
  rect(-175, -8, 350, 15, 8);
  const ln = Math.round(3 + P.density*11);
  for (let i = 0; i < ln; i++) {
    const lv = S.leaves[i % S.leaves.length];
    const lx = -160 + (i + 0.5)/ln * 320 + lv.o*10;
    push(); translate(lx, lv.up > 0 ? -10 : 8);
    rotate(lv.a + (lv.up > 0 ? -0.5 : 0.5) + Math.sin(K.t*1.8 + i)*0.13);
    F(P.style === 'ink' ? faceC : [(H+40)%360, glowOn ? 70 : 42, glowOn ? 38 : 52]);
    SK(lineC, lw > 0 ? 1.4 : 0);
    ellipse(0, lv.up > 0 ? -9*lv.s : 9*lv.s, 10*lv.s, 22*lv.s);
    pop();
  }
  // --- pendulum body under fixed grips ---
  const gw = 36;
  const bcx = Math.sin(sway) * hangLen;
  const bcy = Math.cos(sway*0.9) * hangLen;
  const br = sway * 0.8;
  // dangling legs (behind body), lagging the swing
  const lg = Math.sin(bt*TAU/4 - 1.1) * amp * 1.6 + drift*0.04;
  const legL0 = rot2(-bw*0.20, bh*0.34, br), legR0 = rot2(bw*0.20, bh*0.34, br);
  const legLen = 44 + P.limb*20;
  const fL = [bcx + legL0[0] + Math.sin(br + lg)*legLen*0.4, bcy + legL0[1] + Math.cos(br + lg)*legLen];
  const fR = [bcx + legR0[0] + Math.sin(br + lg + 0.15)*legLen*0.4, bcy + legR0[1] + Math.cos(br + lg + 0.15)*legLen];
  tube(bcx + legL0[0], bcy + legL0[1], fL[0], fL[1], -4, legW);
  tube(bcx + legR0[0], bcy + legR0[1], fR[0], fR[1], 4, legW);
  claws(fL[0], fL[1], br + lg, 0.4);
  claws(fR[0], fR[1], br + lg, 0.4);
  // body + head
  bodyBlob(bcx, bcy, br, 0, Math.sin(bt*TAU/8)*0.12 + drift*0.05);
  // arms in front, from branch grips to shoulders
  const shL = rot2(-bw*0.34, -bh*0.30, br), shR = rot2(bw*0.34, -bh*0.30, br);
  tube(-gw, -2, bcx + shL[0], bcy + shL[1], -16, armW);
  tube( gw, -2, bcx + shR[0], bcy + shR[1], 16, armW);
  claws(-gw, -6, PI + 0.35, 0.6);
  claws( gw, -6, PI - 0.35, 0.6);
} else {
  // --- grounded poses: idle hug / slow wave / half-tempo disco ---
  const isDance = P.pose === 'slowdance';
  const isWave = P.pose === 'wave';
  const hop = Math.abs(Math.sin(bt*TAU/4)) * (3 + 9*e*(isDance ? 1 : 0.35));
  const leanA = isDance ? Math.sin(bt*TAU/4)*0.14 : drift*0.05;
  const hipX = isDance ? Math.sin(bt*TAU/4)*10 : 0;
  // soft shadow
  noStroke(); fill(0, 0, 0, 26); ellipse(0, 2, bw*1.15 + hop*2, 15);
  // stubby legs
  F(fur); SK(lineC, lw);
  rect(-bw*0.24 - 10, -40, 20 + P.chub*5, 42, 9);
  rect( bw*0.24 - 10, -40, 20 + P.chub*5, 42, 9);
  claws(-bw*0.24, -1, -0.3, 0.2);
  claws( bw*0.24, -1, 0.3, 0.2);
  push(); translate(hipX, -hop);
  // body + head (head tilts into the groove, always a bit late)
  const headTilt = isDance ? Math.sin(bt*TAU/4 - 0.7)*0.2 : (isWave ? -0.14 + drift*0.05 : Math.sin(bt*TAU/8)*0.1);
  bodyBlob(0, -bh*0.55 - 36, leanA, late*0.06*e, headTilt);
  // arms
  const shY = -bh*0.85 - 36;
  const shXo = bw*0.36;
  if (isDance) {
    // Saturday-night-fever at HALF speed — diagonal points, alternating
    const mixv = (Math.sin(bt*TAU/8) + 1) / 2;
    const paR = lerp(-2.05, 0.25, mixv);
    const paL = lerp(0.25, -2.05, mixv) + PI - 0.5;
    const hR = [shXo + Math.cos(paR)*armLen*0.78, shY + Math.sin(paR)*armLen*0.78];
    const hL = [-shXo - Math.cos(paL - PI)*armLen*0.78, shY + Math.sin(paL - PI)*armLen*0.78];
    tube( shXo, shY, hR[0], hR[1], 14, armW);
    tube(-shXo, shY, hL[0], hL[1], -14, armW);
    claws(hR[0], hR[1], paR + PI/2, 0.5);
    claws(hL[0], hL[1], -paL + PI/2, 0.5);
    // fingertip disco spark when pointing up
    const up = mixv < 0.35 ? hR : (mixv > 0.65 ? hL : null);
    if (up) { push(); blendMode(ADD); noStroke(); fill((H+60)%360, 60, 100, 40 + K.pulse*40 + A.treble*30); circle(up[0], up[1] - 6, 16 + K.swell*8); blendMode(BLEND); pop(); }
  } else if (isWave) {
    // left hugs belly, right waves in slow motion
    tube(-shXo, shY, -8, shY + bh*0.42, -22, armW);
    const wa = Math.sin(bt*TAU/2) * 0.55;
    const hR = [shXo + armLen*0.55 + Math.sin(wa)*16, shY - armLen*0.62 + Math.abs(Math.cos(wa))*6];
    tube(shXo, shY, hR[0], hR[1], 20, armW);
    claws(hR[0], hR[1], PI + wa, 0.9);
  } else {
    // idle: blissful belly hug, tiny breathing
    const hug = Math.sin(K.t*0.8)*2;
    tube(-shXo, shY, -9, shY + bh*0.42 + hug, -24, armW);
    tube( shXo, shY,  9, shY + bh*0.44 - hug, 24, armW);
    claws(-9, shY + bh*0.42 + hug, 0.5, 0.2);
    claws( 9, shY + bh*0.44 - hug, -0.5, 0.2);
  }
  pop();
}
pop();

// ---------- butterfly friend (world space) ----------
push();
translate(bfx, bfy);
const flap = Math.sin(K.t*9 + Math.sin(K.t*0.7)*3);
const bsz = u*0.016*(1 + 0.2*K.swell)*Math.min(P.scale, 1.6);
noStroke();
fill((H+180)%360, 65, 96, 88);
push(); rotate(-0.5 + flap*0.5); ellipse(-bsz*0.7, 0, bsz*1.5, bsz*0.85); pop();
push(); rotate(0.5 - flap*0.5); ellipse(bsz*0.7, 0, bsz*1.5, bsz*0.85); pop();
fill(H, 30, 25); ellipse(0, 0, bsz*0.35, bsz*1.05);
pop();
blendMode(BLEND);
